/// WP5 step 10: this binding's unknown-field variant, and a check that the LOADED core
/// is the same variant (the u-family export `ak_uencode_ListResultsResponse` absent).
public static class AbiVariant
{
    public const bool UnknownCompiledOut = true;
    public const string Name = "no-unknown";
    /// null when the loaded core matches this binding's variant, else what is wrong.
    public static string CheckLoadedCore()
    {
#if NETCOREAPP3_0_OR_GREATER
        AbiInit.Ensure();
        var h = NativeLibrary.Load(Abi.Lib, typeof(Abi).Assembly, null);
        bool has = NativeLibrary.TryGetExport(h, "ak_uencode_ListResultsResponse", out _);
        if (has == UnknownCompiledOut) return $"the loaded core {(has ? "exports" : "lacks")} ak_uencode_ListResultsResponse: it is not the {Name} variant this binding was rendered for";
        return null;
#else
        return "not checked: NativeLibrary needs .NET Core 3.0 or later";
#endif
    }
}
